/* Ficha de Producto Quick-Shop (Con las 2 sedes de WhatsApp garantizadas y aviso completo de alquiler) */
(function () {
  const dialog = document.getElementById("kalu-product-dialog");
  if (!dialog) return;
  const image = document.getElementById("kalu-product-image"),
    title = document.getElementById("kalu-product-title"),
    code = document.getElementById("kalu-product-code"),
    desc = document.getElementById("kalu-product-description"),
    cat = document.getElementById("kalu-product-category"),
    wa = document.getElementById("kalu-product-wa"),
    note = document.getElementById("kalu-product-note"),
    add = document.getElementById("kalu-product-add");

  // Garantiza que exista el segundo botón de WhatsApp aunque no esté en el HTML
  let waSecondary = document.getElementById("kalu-product-wa-secondary");
  if (!waSecondary && wa && wa.parentElement) {
    waSecondary = document.createElement("a");
    waSecondary.id = "kalu-product-wa-secondary";
    waSecondary.className = "kalu-product-wa-alt";
    waSecondary.target = "_blank";
    waSecondary.rel = "noopener noreferrer";
    wa.insertAdjacentElement("afterend", waSecondary);
  }

  let activeCard = null;
  const escText = (v) => String(v || "").trim();

  const productFromCard = (card) => ({
    name: escText(card.dataset.name || card.querySelector("h3")?.textContent),
    code: escText(card.dataset.code || card.querySelector(".code")?.textContent),
    image: escText(card.dataset.image || card.querySelector("img")?.getAttribute("src")),
    desc: escText(card.dataset.desc || card.querySelector("p")?.textContent),
    category: escText(card.dataset.shopCategory || card.dataset.category || "Producto Kalú"),
    accessory: card.classList.contains("accessory-card"),
  });

  const syncModalAddButton = (pCode) => {
    if (!add) return;
    const added = isSelected({ code: pCode });
    add.textContent = added ? "✓ En mi pedido (Toca para quitar)" : "＋ Agregar a mi selección";
  };

  const openProduct = (card) => {
    const p = productFromCard(card);
    activeCard = card;
    dialog.classList.remove("is-quick");
    if (image) {
      image.src = p.image;
      image.alt = p.name;
      image.hidden = false;
    }
    if (title) title.textContent = p.name;
    if (code) code.textContent = p.code;
    if (desc) desc.textContent = p.desc || "Consulta disponibilidad, tallas y precio.";
    if (cat) cat.textContent = p.category || "Producto Kalú";

    const isRental = /^(DF|TB)/.test(p.code) || card.dataset.shopKind === "rent";
    const mainOffice = isRental ? SEDES.secundaria : SEDES.principal;
    const otherOffice = isRental ? SEDES.principal : SEDES.secundaria;

    const msgMain = `Hola ${mainOffice.nombre}, quiero consultar por ${p.name} (${p.code}).`;
    const msgOther = `Hola ${otherOffice.nombre}, quiero consultar por ${p.name} (${p.code}).`;

    if (wa) {
      wa.href = waLink(mainOffice.numero, msgMain);
      wa.textContent = `WhatsApp ${mainOffice.nombre} · ${displayPhone(mainOffice.numero)}`;
    }
    if (waSecondary) {
      waSecondary.href = waLink(otherOffice.numero, msgOther);
      waSecondary.textContent = `WhatsApp ${otherOffice.nombre} · ${displayPhone(otherOffice.numero)}`;
      waSecondary.hidden = false;
    }

    if (note) {
      if (isRental) {
        note.innerHTML =
          "<strong>💰 Depósito de alquiler:</strong> para reservar se deja un depósito según el traje (se devuelve completo al entregarlo en la fecha acordada).<br><strong>⚠️ Accesorios:</strong> los accesorios que acompañan cada disfraz pueden variar según disponibilidad.";
      } else if (p.accessory) {
        note.innerHTML =
          "<strong>⚠️ Disponibilidad:</strong> los accesorios están sujetos a existencias. Confirma disponibilidad y precio con Kalú por WhatsApp.";
      } else {
        note.textContent = "Precio y disponibilidad se confirman directamente con Kalú por WhatsApp.";
      }
      note.hidden = false;
    }

    syncModalAddButton(p.code);

    const mediaEl = dialog.querySelector(".kalu-product-media");
    if (mediaEl) mediaEl.scrollTop = 0;
    if (typeof dialog.showModal === "function") dialog.showModal();
    else dialog.setAttribute("open", "");
  };

  document.getElementById("kalu-product-close")?.addEventListener("click", () => dialog.close());
  dialog.addEventListener("click", (e) => {
    if (e.target === dialog) dialog.close();
  });

  document.querySelectorAll(".card[data-kalu-product]").forEach((card) => {
    card.addEventListener("click", (e) => {
      if (e.target.closest(".mini-button, a, input, select, textarea")) return;
      openProduct(card);
    });
    card.querySelector(".zoom-button")?.addEventListener("click", (e) => {
      e.stopPropagation();
      openProduct(card);
    });
  });

  add?.addEventListener("click", () => {
    if (!activeCard) return;
    addToOrder(activeCard);
    syncModalAddButton(activeCard.dataset.code);
  });
})();